<?php
/**
 * Self-hosted updates for Bazaar Core and the Bazaar themes.
 *
 * Point client sites at a JSON manifest you host (e.g. on your own server or as a public
 * GitHub release asset), by adding this line to wp-config.php:
 *
 *   define( 'BAZAAR_UPDATE_URL', 'https://example.com/bazaar/manifest.json' );
 *
 * Manifest format (generated by bazaar/bin/build.sh):
 *   {
 *     "bazaar-core":  { "version": "1.0.1", "package": "https://.../bazaar-core-1.0.1.zip",
 *                       "requires": "6.5", "requires_php": "8.0", "tested": "7.1" },
 *     "bazaar-store": { "version": "1.0.1", "package": "https://.../bazaar-store-1.0.1.zip" }
 *   }
 *
 * Updates then appear in Dashboard > Updates like any other plugin/theme, and work with
 * one-click and automatic updates. Only HTTPS packages are accepted.
 *
 * @package BazaarCore
 */

defined( 'ABSPATH' ) || exit;

const BZR_UPDATE_CACHE = 'bzr_update_manifest';

/**
 * Manifest URL, or '' when updates are not configured.
 *
 * @return string
 */
function bzr_update_manifest_url() {
	$url = defined( 'BAZAAR_UPDATE_URL' ) ? (string) BAZAAR_UPDATE_URL : '';
	return (string) apply_filters( 'bzr_update_manifest_url', $url );
}

/**
 * Fetch (and cache for 6 hours) the manifest.
 *
 * @param bool $force Skip the cache.
 * @return array<string,array>
 */
function bzr_update_manifest( $force = false ) {
	$url = bzr_update_manifest_url();
	if ( '' === $url || 0 !== stripos( $url, 'https://' ) ) {
		return array();
	}

	$cached = get_site_transient( BZR_UPDATE_CACHE );
	if ( ! $force && is_array( $cached ) ) {
		return $cached;
	}

	$response = wp_remote_get(
		$url,
		array(
			'timeout' => 10,
			'headers' => array( 'Accept' => 'application/json' ),
		)
	);
	$data     = array();
	if ( ! is_wp_error( $response ) && 200 === wp_remote_retrieve_response_code( $response ) ) {
		$decoded = json_decode( wp_remote_retrieve_body( $response ), true );
		if ( is_array( $decoded ) ) {
			foreach ( $decoded as $slug => $item ) {
				if ( is_array( $item ) && ! empty( $item['version'] ) && ! empty( $item['package'] ) && 0 === stripos( (string) $item['package'], 'https://' ) ) {
					$data[ sanitize_key( $slug ) ] = $item;
				}
			}
		}
	}

	// Cache failures too (for 1 hour) so a dead server does not slow every admin page.
	set_site_transient( BZR_UPDATE_CACHE, $data, $data ? 6 * HOUR_IN_SECONDS : HOUR_IN_SECONDS );
	return $data;
}

/**
 * Add Bazaar Core to the plugin update list.
 *
 * @param object $transient update_plugins transient.
 * @return object
 */
function bzr_update_plugins( $transient ) {
	if ( ! is_object( $transient ) ) {
		return $transient;
	}
	$manifest = bzr_update_manifest();
	if ( empty( $manifest['bazaar-core'] ) ) {
		return $transient;
	}

	$item   = $manifest['bazaar-core'];
	$file   = plugin_basename( BAZAAR_CORE_FILE );
	$update = (object) array(
		'id'           => 'bazaar-core',
		'slug'         => 'bazaar-core',
		'plugin'       => $file,
		'new_version'  => (string) $item['version'],
		'package'      => esc_url_raw( $item['package'] ),
		'url'          => isset( $item['url'] ) ? esc_url_raw( $item['url'] ) : '',
		'requires'     => isset( $item['requires'] ) ? (string) $item['requires'] : '',
		'requires_php' => isset( $item['requires_php'] ) ? (string) $item['requires_php'] : '',
		'tested'       => isset( $item['tested'] ) ? (string) $item['tested'] : '',
	);

	if ( version_compare( $update->new_version, BAZAAR_CORE_VERSION, '>' ) ) {
		$transient->response[ $file ] = $update;
	} else {
		$transient->no_update[ $file ] = $update;
	}
	return $transient;
}
add_filter( 'pre_set_site_transient_update_plugins', 'bzr_update_plugins' );

/**
 * Add installed Bazaar themes to the theme update list.
 *
 * @param object $transient update_themes transient.
 * @return object
 */
function bzr_update_themes( $transient ) {
	if ( ! is_object( $transient ) ) {
		return $transient;
	}
	$manifest = bzr_update_manifest();
	if ( ! $manifest ) {
		return $transient;
	}

	foreach ( wp_get_themes() as $slug => $theme ) {
		// Only our own themes, identified by the "Update URI: bazaar" header and listed in the manifest.
		if ( empty( $manifest[ $slug ] ) || 'bazaar' !== $theme->get( 'UpdateURI' ) ) {
			continue;
		}
		$item   = $manifest[ $slug ];
		$update = array(
			'theme'        => $slug,
			'new_version'  => (string) $item['version'],
			'package'      => esc_url_raw( $item['package'] ),
			'url'          => isset( $item['url'] ) ? esc_url_raw( $item['url'] ) : '',
			'requires'     => isset( $item['requires'] ) ? (string) $item['requires'] : '',
			'requires_php' => isset( $item['requires_php'] ) ? (string) $item['requires_php'] : '',
		);
		if ( version_compare( $update['new_version'], (string) $theme->get( 'Version' ), '>' ) ) {
			$transient->response[ $slug ] = $update;
		} else {
			$transient->no_update[ $slug ] = $update;
		}
	}
	return $transient;
}
add_filter( 'pre_set_site_transient_update_themes', 'bzr_update_themes' );

/**
 * "Check again" on Dashboard > Updates also refreshes our manifest.
 */
function bzr_update_flush_on_force_check() {
	if ( isset( $_GET['force-check'] ) && current_user_can( 'update_plugins' ) ) { // phpcs:ignore WordPress.Security.NonceVerification -- core's own read-only flag.
		delete_site_transient( BZR_UPDATE_CACHE );
	}
}
add_action( 'load-update-core.php', 'bzr_update_flush_on_force_check' );

/**
 * Plugin details pop-up ("View version x.y details").
 *
 * @param false|object|array $result Default result.
 * @param string             $action API action.
 * @param object             $args   Request args.
 * @return false|object
 */
function bzr_update_plugin_info( $result, $action, $args ) {
	if ( 'plugin_information' !== $action || empty( $args->slug ) || 'bazaar-core' !== $args->slug ) {
		return $result;
	}
	$manifest = bzr_update_manifest();
	if ( empty( $manifest['bazaar-core'] ) ) {
		return $result;
	}
	$item = $manifest['bazaar-core'];
	return (object) array(
		'name'          => 'Bazaar Core',
		'slug'          => 'bazaar-core',
		'version'       => (string) $item['version'],
		'requires'      => isset( $item['requires'] ) ? (string) $item['requires'] : '',
		'requires_php'  => isset( $item['requires_php'] ) ? (string) $item['requires_php'] : '',
		'tested'        => isset( $item['tested'] ) ? (string) $item['tested'] : '',
		'download_link' => esc_url_raw( $item['package'] ),
		'sections'      => array(
			'changelog' => isset( $item['changelog'] ) ? wp_kses_post( $item['changelog'] ) : '',
		),
	);
}
add_filter( 'plugins_api', 'bzr_update_plugin_info', 10, 3 );
